codeExamples.code:
-- Schema inherits the parent catalog's managed location
CREATE SCHEMA IF NOT EXISTS sales_catalog.bronze
  COMMENT 'Raw ingested sales data';

-- Schema with its own managed location (requires an external location)
CREATE SCHEMA IF NOT EXISTS sales_catalog.silver
  MANAGED LOCATION 's3://company-uc/sales/silver'
  COMMENT 'Cleaned and conformed sales data';

-- DATABASE is an exact synonym for SCHEMA
CREATE DATABASE IF NOT EXISTS sales_catalog.gold;

SHOW SCHEMAS IN sales_catalog;

-- Allow a group to traverse into the catalog and schema
GRANT USE CATALOG ON CATALOG sales_catalog TO `analysts`;
GRANT USE SCHEMA  ON SCHEMA  sales_catalog.gold TO `analysts`;

-- One grant covers every current and future table/view in the schema
GRANT SELECT ON SCHEMA sales_catalog.gold TO `analysts`;

-- Let an ingestion service principal create and write tables
GRANT USE SCHEMA, CREATE TABLE
  ON SCHEMA sales_catalog.bronze
  TO `ingestion_sp`;

SHOW GRANTS ON SCHEMA sales_catalog.gold;

USE CATALOG sales_catalog;
USE SCHEMA bronze;

-- A managed Delta table
CREATE TABLE orders (order_id BIGINT, customer_id BIGINT, amount DECIMAL(10,2));

-- A view over that table
CREATE VIEW high_value_orders AS
  SELECT * FROM orders WHERE amount > 1000;

-- A volume for non-tabular files (CSV/JSON/images) in the same schema
CREATE VOLUME raw_files;

-- A SQL UDF stored in the schema
CREATE FUNCTION clean_amount(x DECIMAL(10,2))
  RETURNS DECIMAL(10,2)
  RETURN COALESCE(x, 0);

SHOW TABLES;
SHOW VOLUMES;
